/* STOCK · Gestión de cocina. Aplicación local-first y sin dependencias externas. */
(() => {
  'use strict';
  const STORE_KEY = 'stock_vikinga_app_v1';
  const $ = (sel, root=document) => root.querySelector(sel);
  const $$ = (sel, root=document) => [...root.querySelectorAll(sel)];
  const todayISO = () => { const d=new Date(); d.setMinutes(d.getMinutes()-d.getTimezoneOffset()); return d.toISOString().slice(0,10); };
  const dateAdd = (date, days) => { if(!date)return ''; const d=new Date(`${date}T12:00:00`); d.setDate(d.getDate()+Number(days||0)); return d.toISOString().slice(0,10); };
  const parseNumber = v => { if(typeof v==='number') return v; const n=Number(String(v??'').trim().replace(',','.')); return Number.isFinite(n)?n:0; };
  const fmt = (n, max=2) => Number(n||0).toLocaleString('es-AR',{maximumFractionDigits:max});
  const fmtDate = value => value ? new Date(`${value}T12:00:00`).toLocaleDateString('es-AR') : 'Sin fecha';
  const daysUntil = value => value ? Math.ceil((new Date(`${value}T00:00:00`).getTime()-new Date(`${todayISO()}T00:00:00`).getTime())/86400000) : null;
  const id = () => Math.random().toString(36).slice(2,10)+Date.now().toString(36).slice(-4);
  const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const weekdays = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
  const categoryList = ['Proteínas / Carnes','Verdulería','Encurtidos','Preparaciones','Salsas','Panadería','Congelados','Despensa','Limpieza e insumos'];
  function product(id,name,category,unit,control='number',opts={}) { return {id,name,category,unit,control,wa:true,expiryMode:'none',track:'none',frozen:false,shelfLifeDays:null,bagWeightKg:null,active:true,...opts}; }

  const defaultProducts = [
    product('carne-molida','Carne molida','Proteínas / Carnes','kg','number',{expiryMode:'production',shelfLifeDays:3,wa:true}),
    product('medallones','Medallones de 100 g','Proteínas / Carnes','unidades','medallions',{expiryMode:'production',shelfLifeDays:3,wa:true}),
    product('lomos','Lomos porcionados','Proteínas / Carnes','porciones','number',{frozen:true,wa:true}),
    product('bondiola','Bondiola desmechada','Proteínas / Carnes','porciones','number',{frozen:true,wa:true}),
    ...['Lechuga','Tomate','Verdeo','Perejil','Ciboulette','Palta','Rúcula','Ajo fresco','Cebolla','Cebolla morada','Pimiento rojo'].map((n,i)=>product('verd-'+i,n,'Verdulería',n==='Ajo fresco'?'unidades':'kg','number',{expiryMode:'dateonly',wa:false})),
    product('huevos','Huevos','Verdulería','unidades','number',{expiryMode:'dateonly',wa:false}),
    product('pickles-cebolla','Pickles de cebolla morada','Encurtidos','kg','number',{track:'lots',expiryMode:'lots',wa:false}),
    product('pickles-picante','Pickles de picante','Encurtidos','kg','number',{track:'lots',expiryMode:'lots',wa:false}),
    product('pickles-pepino','Pickles de pepino','Encurtidos','kg','number',{track:'lots',expiryMode:'lots',wa:false}),
    ...[
      'Cebolla Crispi','Cebolla caramelizada','Pimiento asado','Cebolla cortada','Pimiento cortado','Lechuga lavada','Lechuga cortada','Tomate cortado','Guacamole preparado','Cebolla morada cortada','Panceta cocinada','Panceta sin cocinar','Dambo feteado','Jamón feteado','Roquefort porcionado','Huevos duros'
    ].map((n,i)=>product('prep-'+i,n,'Preparaciones','kg','number',{track:'lots',expiryMode:'lots',wa:false})),
    ...['Mil islas','Staker','Valjala','Ranch','Alioli','Tasty','Tártara'].map((n,i)=>product('salsa-'+i,n,'Salsas','mamadera','sauce',{track:'sauce',expiryMode:'sauce',wa:false})),
    ...['Panes de hamburguesa','Panes de lomo','Panes de bondiola','Panes de chipa'].map((n,i)=>product('pan-'+i,n,'Panadería','unidades','number',{wa:true})),
    product('papas','Papas','Congelados','bolsas + kg','potatoes',{wa:true,bagWeightKg:null}),
    ...['Nuggets','Aros de cebolla','Deluxe de hongos','Hamburguesas de pollo','Hamburguesas veggie de garbanzos'].map((n,i)=>product('cong-'+i,n,'Congelados','unidades','number',{wa:false})),
    ...['Dambo','Cheddar','Provolón','Roquefort'].map((n,i)=>product('queso-'+i,n,'Despensa','kg','number',{wa:false})),
    ...['Mayonesa','Ketchup','Mostaza','Barbacoa'].map((n,i)=>product('aderezo-'+i,n,'Despensa','unidades','number',{wa:false})),
    product('leche','Leche','Despensa','litros','number',{expiryMode:'production',wa:false}),
    product('yogur','Yogur griego','Despensa','unidades','number',{wa:false}),
    product('crema','Crema de leche','Despensa','unidades','number',{wa:false}),
    product('jamon','Jamón','Despensa','kg','number',{wa:false}),
    ...['Ajo en polvo','Pimienta negra','Sal','Azúcar','Paprika','Ajinomoto','Harina'].map((n,i)=>product('cond-'+i,n,'Despensa','unidades','number',{wa:false})),
    product('escobillon','Escobillón','Limpieza e insumos','estado','reusable',{wa:false}),
    product('mopa','Mopa','Limpieza e insumos','estado','reusable',{wa:false}),
    ...['Detergente','Desengrasante','Lavandina','Limpia pisos','Desincrustante para plancha'].map((n,i)=>product('limp-'+i,n,'Limpieza e insumos','unidades','number',{wa:false})),
    ...['Bolsas de basura','Fólex para hamburguesas','Fólex para fiambre','Papel aluminio','Aluminio para hamburguesa','Papel parafinado','Dips','Tapas para dips'].map((n,i)=>product('insumo-'+i,n,'Limpieza e insumos','unidades','number',{wa:false}))
  ];
  // Todos los productos participan del mensaje cuando estén bajos; la selección puede ajustarse en Configuración.
  defaultProducts.forEach(p => { p.wa = true; });

  function freshInventory(p) {
    return {qty:p.control==='potatoes'?{bags:0,openKg:0}:p.control==='sauce'?'llena':p.control==='reusable'?'bien':0,status:p.control==='reusable'?'bien':'sin-registro',frozenQty:0,madeDate:'',expiresAt:'',batches:[],sauce:{level:'llena',madeDate:'',expiresAt:'',batches:[]},updatedAt:''};
  }
  function createInitialState() {
    const products=defaultProducts.map(p=>({...p}));
    const inventory={}; products.forEach(p=>inventory[p.id]=freshInventory(p));
    return {version:1,products,categories:[...categoryList],inventory,closures:[],entries:[],shifts:[],orders:[],settings:{hourlyRate:0,ordinaryDays:5,peakDays:2,manualUsage:{}},createdAt:new Date().toISOString()};
  }
  function loadState() {
    try { const raw=localStorage.getItem(STORE_KEY); if(!raw)return createInitialState(); const data=JSON.parse(raw); if(!data||!Array.isArray(data.products))return createInitialState();
      const base=createInitialState();
      return {...base,...data,settings:{...base.settings,...(data.settings||{}),manualUsage:{...(base.settings.manualUsage||{}),...((data.settings||{}).manualUsage||{})}},inventory:{...base.inventory,...(data.inventory||{})}};
    } catch(e) { console.warn('No se pudo leer el almacenamiento local.',e); return createInitialState(); }
  }
  let state=loadState();
  let currentPage='inicio';
  let selectedCategory='Todas';
  let stockQuery='';
  let closureDraft={};
  let toastTimer;
  function saveState(){ try{localStorage.setItem(STORE_KEY,JSON.stringify(state));}catch(e){toast('No se pudo guardar. Revisá el espacio disponible del navegador.');console.error(e);} }
  function getProduct(pid){return state.products.find(p=>p.id===pid);}
  function getInv(pid){const p=getProduct(pid);if(!state.inventory[pid]&&p)state.inventory[pid]=freshInventory(p);return state.inventory[pid]||{};}
  function activeProducts(){return state.products.filter(p=>p.active!==false);}
  function productGroups(){const groups={};state.categories.forEach(c=>groups[c]=[]);activeProducts().forEach(p=>(groups[p.category]??=[]).push(p));return groups;}
  function qtyNumeric(p,inv){if(!p||!inv)return 0;if(p.control==='potatoes')return p.bagWeightKg>0?(Number(inv.qty?.bags)||0)*Number(p.bagWeightKg)+(Number(inv.qty?.openKg)||0):null;if(p.control==='sauce')return inv.sauce?.level==='llena'?1:(inv.sauce?.level==='mitad'?0.5:(inv.sauce?.level==='por terminarse'?0.2:0));if(p.control==='reusable')return inv.qty==='bien'?1:0;return parseNumber(inv.qty);}
  function qtyDisplay(p,inv){if(!p||!inv)return '—';if(p.control==='potatoes')return `${fmt(inv.qty?.bags||0,0)} bolsas + ${fmt(inv.qty?.openKg||0)} kg`;if(p.control==='sauce')return inv.sauce?.level||'llena';if(p.control==='reusable')return inv.qty==='cambiar'?'Cambiar':'Está bien';return `${fmt(inv.qty)} ${p.unit}`;}
  function statusText(v){return v==='poco'?'Hay poco':v==='no'?'No hay':v==='hay'?'Hay':v==='cambiar'?'Cambiar':v==='bien'?'Está bien':'Sin registrar';}
  function statusClass(v){return v==='poco'?'warning':v==='no'?'danger':'ok';}
  function toast(message){const el=$('#toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600);}
  const navItems=[['inicio','⌂','Inicio'],['cierre','▣','Hacer stock'],['stock','▦','Stock actual'],['rotacion','↗','Rotación'],['ingresos','＋','Ingresos'],['pedidos','🛒','Pedidos'],['trabajo','◷','Mi trabajo'],['historial','◴','Historial'],['configuracion','⚙','Configuración']];
  function navHTML(active,compact=false){const names=compact?navItems.slice(0,4):navItems;return names.map(([key,icon,label])=>`<button class="nav-btn ${active===key?'active':''}" data-go="${key}"><span class="nav-icon">${icon}</span><span>${label}</span></button>`).join('')+(compact?`<button class="nav-btn" data-action="more-menu"><span class="nav-icon">•••</span><span>Más</span></button>`:'');}
  function drawNavigation(){ $('#side-nav').innerHTML=navHTML(currentPage);$('#mobile-nav').innerHTML=navHTML(currentPage,true); }
  function go(page){currentPage=page;drawNavigation();renderPage();window.scrollTo({top:0,behavior:'smooth'});}
  function pageHead(title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">STOCK · GESTIÓN DE COCINA</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
  function panel(title,body,sub=''){return `<section class="panel"><h2 class="panel-title">${title}</h2>${sub?`<p class="panel-sub">${sub}</p>`:''}${body}</section>`;}
  function getAllExpirations(){const list=[];activeProducts().forEach(p=>{const inv=getInv(p.id);if(p.expiryMode==='lots'||p.track==='lots'){(inv.batches||[]).filter(b=>b.status==='available'&&b.expiresAt).forEach(b=>list.push({product:p,kind:'lote',label:b.label||'Lote',expiresAt:b.expiresAt,qty:b.qty,id:b.id}));}else if(p.control==='sauce'){const s=inv.sauce||{};if(s.expiresAt)list.push({product:p,kind:'mamadera',label:'Mamadera en uso',expiresAt:s.expiresAt,qty:s.level,id:'active'});(s.batches||[]).filter(b=>b.status==='available'&&b.expiresAt).forEach(b=>list.push({product:p,kind:'reserva',label:'Reserva',expiresAt:b.expiresAt,qty:b.qty,id:b.id}));}else if(inv.expiresAt){const currentQty=p.control==='medallions'?Math.max(0,parseNumber(inv.qty)-parseNumber(inv.frozenQty)):qtyNumeric(p,inv);if(currentQty>0){list.push({product:p,kind:'producto',label:'Stock actual',expiresAt:inv.expiresAt,qty:qtyDisplay(p,inv),id:'current'});}}});return list.sort((a,b)=>a.expiresAt.localeCompare(b.expiresAt));}
  function expiryBadge(date){const d=daysUntil(date);if(d===null)return '<span class="status-badge neutral">Sin fecha</span>';if(d<0)return `<span class="status-badge danger">Vencido hace ${Math.abs(d)} día(s)</span>`;if(d<=1)return `<span class="status-badge warning">${d===0?'Vence hoy':'Vence mañana'}</span>`;return `<span class="status-badge ok">En buen estado</span>`;}
  function dashboard(){
    const products=activeProducts(), expiries=getAllExpirations(), imminent=expiries.filter(x=>daysUntil(x.expiresAt)<=1), low=products.filter(p=>['poco','no'].includes(getInv(p.id).status));
    const total=products.length,withExpiry=expiries.length,latest=state.closures.slice().sort((a,b)=>b.date.localeCompare(a.date))[0];
    const avg=computeUsage();const used=Object.values(avg).filter(x=>x.total>0).length;
    const recommendations=buildRecommendations().slice(0,4);
    const cards=`<div class="grid grid-4">
      <div class="card stat-card"><span class="stat-icon">▦</span><div class="stat-label">Productos configurados</div><div class="stat-value">${total}</div><div class="stat-foot">En el inventario</div></div>
      <div class="card stat-card"><span class="stat-icon">⚑</span><div class="stat-label">Bajo stock</div><div class="stat-value">${low.length}</div><div class="stat-foot">Según el último cierre</div></div>
      <div class="card stat-card"><span class="stat-icon">⌛</span><div class="stat-label">Vencimientos cercanos</div><div class="stat-value">${imminent.length}</div><div class="stat-foot">Hoy o mañana</div></div>
      <div class="card stat-card"><span class="stat-icon">↗</span><div class="stat-label">Productos con datos de uso</div><div class="stat-value">${used}</div><div class="stat-foot">Estimaciones basadas en cierres</div></div>
    </div>`;
    const expHTML=expiries.slice(0,5).map(x=>`<div class="list-row"><div class="row-main"><div class="row-title">${esc(x.product.name)} · ${esc(x.label)}</div><div class="row-note">${fmtDate(x.expiresAt)}</div></div>${expiryBadge(x.expiresAt)}</div>`).join('')||'<div class="empty-state">Todavía no hay vencimientos cargados.<strong>Podés registrar fechas desde Stock actual.</strong></div>';
    const lowHTML=low.slice(0,5).map(p=>`<div class="list-row"><div class="row-main"><div class="row-title">${esc(p.name)}</div><div class="row-note">${qtyDisplay(p,getInv(p.id))}</div></div><span class="status-badge ${statusClass(getInv(p.id).status)}">${statusText(getInv(p.id).status)}</span></div>`).join('')||'<div class="empty-state">No hay productos marcados como bajo stock.</div>';
    const recHTML=recommendations.map(r=>`<div class="list-row"><div class="row-main"><div class="row-title">${esc(r.title)}</div><div class="row-note">${esc(r.text)}</div></div><span class="tag">${esc(r.tag)}</span></div>`).join('')||'<div class="empty-state">Aún faltan registros para generar recomendaciones.<strong>Los ingresos y cierres van a alimentar esta sección.</strong></div>';
    const chart=renderMiniChart(avg);
    $('#main').innerHTML=pageHead('Inicio','Un vistazo rápido a la cocina, los vencimientos y la rotación.',`<button class="btn" data-go="cierre">＋ Hacer cierre</button><button class="btn secondary" data-go="ingresos">Registrar ingreso</button>`)+cards+`<div class="grid grid-2" style="margin-top:15px">${panel('Próximos vencimientos',expHTML)}${panel('Estado del stock',lowHTML)}</div><div class="grid grid-2">${panel('Rotación registrada',chart,'Comparación estimada a partir de cierres consecutivos.')}${panel('Sugerencias de planificación',recHTML)}</div><div class="panel"><div class="panel-title">Actividad reciente <button class="btn ghost small" data-go="historial">Ver historial</button></div>${latest?`<div class="list-row"><div class="row-main"><div class="row-title">Último cierre guardado</div><div class="row-note">${fmtDate(latest.date)} · ${latest.items.length} productos registrados</div></div><span class="status-badge ok">Guardado</span></div>`:'<div class="empty-state">Todavía no hay cierres guardados.<strong>El primer cierre va a iniciar el historial.</strong></div>'}</div>`;
  }
  function renderMiniChart(stats){const arr=Object.entries(stats).filter(([pid,s])=>s.total>0).sort((a,b)=>b[1].total-a[1].total).slice(0,5);if(!arr.length)return '<div class="empty-state">Cuando tengas al menos dos cierres, aparecerá una comparación de uso.</div>';const max=Math.max(...arr.map(x=>x[1].total),1);return `<div class="bar-chart">${arr.map(([pid,s])=>{const p=getProduct(pid);const h=Math.max(4,Math.round(s.total/max*120));return `<div class="bar-group"><div class="bar" style="height:${h}px" title="${fmt(s.total)} consumidos"></div><span class="bar-label">${esc((p?.name||pid).slice(0,9))}</span></div>`;}).join('')}</div><div class="bar-legend"><span><i class="dot"></i>Salida estimada acumulada</span></div>`;}

  function closureInitial(p){const inv=getInv(p.id);if(p.control==='potatoes')return {bags:inv.qty?.bags??'',openKg:inv.qty?.openKg??'',status:['hay','poco','no'].includes(inv.status)?inv.status:'hay'};if(p.control==='sauce')return {level:inv.sauce?.level||'llena',status:['hay','poco','no'].includes(inv.status)?inv.status:'hay'};if(p.control==='medallions')return {qty:inv.qty??'',frozenQty:inv.frozenQty??0,status:['hay','poco','no'].includes(inv.status)?inv.status:'hay'};if(p.control==='reusable')return {qty:inv.qty||'bien',status:inv.status||'hay'};return {qty:inv.qty??'',status:['hay','poco','no'].includes(inv.status)?inv.status:'hay'};}
  function renderClosure(){
    const groups=productGroups();
    let html=pageHead('Hacer stock','Registrá cantidades, pesos y estados del cierre. Las fechas y los lotes se administran desde Stock actual.',`<button class="btn secondary" data-action="copy-last-message">Copiar último mensaje</button>`);
    html+=`<div class="alert-box" style="margin-bottom:14px">El cierre actualiza las cantidades del inventario y guarda los estados Hay / Hay poco / No hay. No modifica fechas ni lotes. Al guardar, se arma el mensaje de WhatsApp.</div>`;
    for(const cat of state.categories){const ps=groups[cat]||[];if(!ps.length)continue;html+=`<details class="close-category" open><summary><span>${esc(cat)}</span><span class="tag">${ps.length} productos</span></summary>`;
      ps.forEach(p=>{const v=closureInitial(p);html+=`<div class="close-item" data-close-product="${p.id}"><div class="close-name">${esc(p.name)} <span class="close-unit">${esc(p.unit)}</span></div>`;
        if(p.control==='potatoes')html+=`<div class="close-qty"><div class="mini-field"><span>Bolsas cerradas</span><input type="number" min="0" step="1" data-field="bags" value="${esc(v.bags)}" placeholder="0"></div><div class="mini-field"><span>Bolsa abierta (kg)</span><input type="number" min="0" step="0.1" data-field="openKg" value="${esc(v.openKg)}" placeholder="0"></div></div>`;
        else if(p.control==='sauce')html+=`<div class="close-qty"><div class="mini-field"><span>Mamadera</span><select data-field="level"><option value="llena" ${v.level==='llena'?'selected':''}>Llena</option><option value="mitad" ${v.level==='mitad'?'selected':''}>A la mitad</option><option value="por terminarse" ${v.level==='por terminarse'?'selected':''}>Por terminarse</option></select></div></div>`;
        else if(p.control==='reusable')html+=`<div class="close-qty"><div class="mini-field"><span>Estado del elemento</span><select data-field="qty"><option value="bien" ${v.qty==='bien'?'selected':''}>Está bien</option><option value="cambiar" ${v.qty==='cambiar'?'selected':''}>Cambiar</option></select></div></div>`;
        else if(p.control==='medallions')html+=`<div class="close-qty"><div class="mini-field"><span>Total (un.)</span><input type="number" min="0" step="1" data-field="qty" value="${esc(v.qty)}" placeholder="0"></div><div class="mini-field"><span>Congelados (un.)</span><input type="number" min="0" step="1" data-field="frozenQty" value="${esc(v.frozenQty)}" placeholder="0"></div></div>`;
        else html+=`<div class="close-qty"><div class="mini-field"><span>Cantidad / peso (${esc(p.unit)})</span><input type="number" min="0" step="any" data-field="qty" value="${esc(v.qty)}" placeholder="0"></div></div>`;
        html+=p.control==='reusable'?`<div class="close-status"><span class="tag">Elemento reutilizable</span></div></div>`:`<div class="close-status"><select data-field="status" aria-label="Estado de ${esc(p.name)}"><option value="hay" ${v.status==='hay'?'selected':''}>Hay</option><option value="poco" ${v.status==='poco'?'selected':''}>Hay poco</option><option value="no" ${v.status==='no'?'selected':''}>No hay</option></select></div></div>`;
      });html+='</details>';}
    html+=`<div class="panel"><div class="form-grid"><div class="field"><label for="closure-date">Fecha del cierre</label><input id="closure-date" type="date" value="${todayISO()}"></div><div class="field"><label>Productos incluidos</label><input value="${activeProducts().length} productos" disabled></div></div><div class="btn-row" style="margin-top:14px"><button class="btn" data-action="save-close">Guardar cierre y generar mensaje</button><button class="btn secondary" data-action="preview-message">Vista previa del mensaje</button></div></div><div id="closure-preview"></div>`;
    $('#main').innerHTML=html;
  }
  function collectClosure(){const items=[];activeProducts().forEach(p=>{const row=$(`[data-close-product="${p.id}"]`);if(!row)return;const value=f=>row.querySelector(`[data-field="${f}"]`)?.value??'';const item={productId:p.id,status:p.control==='reusable'?(value('qty')||'bien'):(value('status')||'no')};if(p.control==='potatoes')item.qty={bags:Math.max(0,parseNumber(value('bags'))),openKg:Math.max(0,parseNumber(value('openKg')))};else if(p.control==='sauce')item.qty=value('level')||'llena';else if(p.control==='reusable')item.qty=value('qty')||'bien';else {item.qty=Math.max(0,parseNumber(value('qty')));if(p.control==='medallions')item.frozenQty=Math.min(item.qty,Math.max(0,parseNumber(value('frozenQty'))));}items.push(item);});return items;}
  function formatItemQty(p,item,inv){if(p.control==='potatoes'){const q=item?.qty||inv?.qty||{};return `${fmt(q.bags,0)} bolsas + ${fmt(q.openKg)} kg`;}if(p.control==='sauce')return item?.qty||inv?.sauce?.level||'sin dato';if(p.control==='reusable')return item?.qty==='cambiar'?'Cambiar':'Está bien';const q=item?.qty??inv?.qty??0;if(p.control==='medallions'){const frozen=item?.frozenQty??inv?.frozenQty??0;return `${fmt(q)} unidades, ${fmt(frozen,0)} congelados`;}return `${fmt(q)} ${p.unit}`;}
  function buildWhatsAppMessage(close){const map=new Map((close?.items||[]).map(i=>[i.productId,i]));const lines=[];const addLine=(p,item,mode='always')=>{if(!p||!item||p.wa===false)return;const inv=getInv(p.id);if(p.control==='reusable'){if((item.qty||item.status)==='cambiar')lines.push(`• ${p.name}: Cambiar`);return;}let line=`• ${p.name}: `;if(item.status==='no')line+='No hay';else if(item.status==='poco'){line+='Hay poco';const hasQty=p.control==='sauce'?Boolean(item.qty):p.control==='potatoes'?(parseNumber(item.qty?.bags)+parseNumber(item.qty?.openKg)>0):parseNumber(item.qty)>0;const extra=hasQty?formatItemQty(p,item,inv):'';if(extra&&extra!=='sin dato')line+=` (${extra})`;}else line+=formatItemQty(p,item,inv);lines.push(line);};
    lines.push(`STOCK · CIERRE ${fmtDate(close?.date||todayISO())}`,'');
    lines.push('PANES Y PAPAS');activeProducts().filter(p=>p.category==='Panadería'||p.id==='papas').forEach(p=>addLine(p,map.get(p.id)||{status:getInv(p.id).status||'no',qty:getInv(p.id).qty},'always'));
    lines.push('','CARNES');activeProducts().filter(p=>p.category==='Proteínas / Carnes').forEach(p=>addLine(p,map.get(p.id)||{status:getInv(p.id).status||'no',qty:getInv(p.id).qty,frozenQty:getInv(p.id).frozenQty},'always'));
    const low=activeProducts().filter(p=>!['Panadería','Proteínas / Carnes'].includes(p.category)&&p.id!=='papas'&&p.wa!==false).filter(p=>p.control==='reusable'?((map.get(p.id)?.qty||getInv(p.id).qty)==='cambiar'):['poco','no'].includes(map.get(p.id)?.status||getInv(p.id).status));
    if(low.length){lines.push('','BAJO STOCK');low.forEach(p=>{const item=map.get(p.id)||{status:getInv(p.id).status,qty:getInv(p.id).qty};addLine(p,item);});}
    return lines.join('\n').replace(/\n{3,}/g,'\n\n');
  }
  function saveClose(){const date=$('#closure-date')?.value||todayISO();const items=collectClosure();items.forEach(item=>{const p=getProduct(item.productId),inv=getInv(item.productId);inv.qty=item.qty&&typeof item.qty==='object'?{...item.qty}:item.qty;inv.status=item.status;inv.updatedAt=new Date().toISOString();if(p.control==='medallions')inv.frozenQty=item.frozenQty||0;if(p.control==='sauce')inv.sauce.level=item.qty;if(p.control==='reusable'){inv.qty=item.qty;inv.status=item.qty;}});const close={id:id(),date,createdAt:new Date().toISOString(),items:items.map(item=>({...item,qty:item.qty&&typeof item.qty==='object'?{...item.qty}:item.qty}))};state.closures.push(close);state.closures.sort((a,b)=>a.date.localeCompare(b.date));saveState();const msg=buildWhatsAppMessage(close);$('#closure-preview').innerHTML=`<section class="panel"><h2 class="panel-title">Mensaje listo para WhatsApp</h2><textarea id="wa-message" class="control" rows="16" style="font-family:inherit;white-space:pre-wrap">${esc(msg)}</textarea><div class="btn-row" style="margin-top:10px"><button class="btn" data-action="copy-message">Copiar mensaje</button><button class="btn secondary" data-action="share-message">Compartir</button></div></section>`;toast('Cierre guardado y stock actualizado.');drawNavigation();}
  function previewMessage(){const items=collectClosure();const close={date:$('#closure-date')?.value||todayISO(),items};$('#closure-preview').innerHTML=`<section class="panel"><h2 class="panel-title">Vista previa del mensaje</h2><textarea id="wa-message" class="control" rows="15">${esc(buildWhatsAppMessage(close))}</textarea><div class="btn-row" style="margin-top:10px"><button class="btn" data-action="copy-message">Copiar mensaje</button></div></section>`;}
  async function copyMessage(){const text=$('#wa-message')?.value||buildWhatsAppMessage(state.closures.slice(-1)[0]||{date:todayISO(),items:[]});try{await navigator.clipboard.writeText(text);toast('Mensaje copiado.');}catch(e){const ta=$('#wa-message');if(ta){ta.focus();ta.select();document.execCommand('copy');toast('Mensaje copiado.');}else toast('No se pudo copiar automáticamente.');}}
  async function shareMessage(){const text=$('#wa-message')?.value||'';if(navigator.share){try{await navigator.share({text});}catch(e){}}else copyMessage();}

  function productExpirySummary(p,inv){if(p.track==='lots'){const active=(inv.batches||[]).filter(b=>b.status==='available');const soon=active.filter(b=>b.expiresAt).sort((a,b)=>a.expiresAt.localeCompare(b.expiresAt))[0];return `<div class="expiry-line">${active.length} lote(s) disponible(s)${soon?` · próximo: ${fmtDate(soon.expiresAt)}`:''}</div>`;}if(p.control==='sauce'){const s=inv.sauce||{};return `<div class="expiry-line">Mamadera: ${expiryBadge(s.expiresAt).replace('status-badge','status-badge')} · ${((s.batches||[]).filter(b=>b.status==='available')).length} reserva(s)</div>`;}if(p.control==='medallions'&&parseNumber(inv.qty)>0&&parseNumber(inv.qty)<=parseNumber(inv.frozenQty))return '<div class="expiry-line">Medallones congelados · sin control de vencimiento</div>';if(inv.expiresAt&&(p.control!=='medallions'||parseNumber(inv.qty)>parseNumber(inv.frozenQty))){const d=daysUntil(inv.expiresAt);return `<div class="expiry-line ${d<0?'danger-text':d<=1?'warning-text':''}">Vence: ${fmtDate(inv.expiresAt)}</div>`;}return p.expiryMode!=='none'?'<div class="expiry-line">Vencimiento sin registrar</div>':'';}
  function renderStock(){const groups=productGroups();let html=pageHead('Stock actual','Inventario vivo: las cantidades vienen del último cierre y se administran acá los vencimientos, lotes y mamaderas.',`<button class="btn" data-go="ingresos">＋ Registrar ingreso</button>`);
    html+=`<div class="filter-bar"><input id="stock-search" type="search" placeholder="Buscar producto…" value="${esc(stockQuery)}"><select id="stock-category"><option>Todas</option>${state.categories.map(c=>`<option ${selectedCategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select><button class="btn secondary small" data-action="refresh-stock">Actualizar</button></div>`;
    const products=activeProducts().filter(p=>(selectedCategory==='Todas'||p.category===selectedCategory)&&p.name.toLowerCase().includes(stockQuery.toLowerCase()));
    if(!products.length)html+='<div class="empty-state">No encontramos productos con ese filtro.</div>';
    for(const cat of state.categories){const ps=products.filter(p=>p.category===cat);if(!ps.length)continue;html+=`<h2 class="section-heading">${esc(cat)}</h2><div class="product-grid">${ps.map(p=>renderProductCard(p)).join('')}</div>`;}
    $('#main').innerHTML=html;
  }
  function renderProductCard(p){const inv=getInv(p.id),status=p.control==='reusable'?(inv.qty==='cambiar'?'poco':'hay'):(inv.status||'sin-registro');let badgeLabel=p.control==='reusable'?(inv.qty==='cambiar'?'Cambiar':'Está bien'):statusText(status);let badgeClass=status==='sin-registro'?'neutral':statusClass(status);let subtitle=`${esc(p.category)} · ${esc(p.unit)}${p.frozen?' · congelado':''}`;let qty=qtyDisplay(p,inv);if(p.control==='medallions')subtitle+=` · ${fmt(inv.frozenQty||0,0)} congelados / ${fmt(Math.max(0,parseNumber(inv.qty)-(inv.frozenQty||0)),0)} frescos`;
    return `<article class="product-card"><div class="product-card-head"><div><div class="product-name">${esc(p.name)}</div><div class="product-meta">${subtitle}</div></div><span class="status-badge ${badgeClass}">${badgeLabel}</span></div><div class="product-qty">${qty}</div>${productExpirySummary(p,inv)}${p.track==='lots'?`<div class="row-note">Lotes activos: ${(inv.batches||[]).filter(b=>b.status==='available').length}</div>`:''}${p.control==='sauce'?`<div class="row-note">Mamadera: ${esc(inv.sauce?.level||'llena')} · Reservas: ${(inv.sauce?.batches||[]).filter(b=>b.status==='available').length}</div>`:''}<div class="product-actions"><button class="btn secondary small" data-action="edit-stock" data-id="${p.id}">Editar stock</button>${p.track==='lots'?`<button class="btn ghost small" data-action="manage-lots" data-id="${p.id}">Ver lotes</button>`:''}${p.control==='sauce'?`<button class="btn ghost small" data-action="manage-sauce" data-id="${p.id}">Mamadera / reservas</button>`:''}</div></article>`;
  }
  function renderStockEditModal(pid){const p=getProduct(pid),inv=getInv(pid);if(!p)return;let fields='';
    if(p.control==='potatoes')fields+=`<div class="field"><label>Bolsas cerradas</label><input name="bags" type="number" min="0" step="1" value="${esc(inv.qty?.bags||0)}"></div><div class="field"><label>Bolsa abierta (kg)</label><input name="openKg" type="number" min="0" step="0.1" value="${esc(inv.qty?.openKg||0)}"></div>`;
    else if(p.control==='sauce')fields+=`<div class="field"><label>Estado de la mamadera</label><select name="level"><option value="llena" ${inv.sauce?.level==='llena'?'selected':''}>Llena</option><option value="mitad" ${inv.sauce?.level==='mitad'?'selected':''}>A la mitad</option><option value="por terminarse" ${inv.sauce?.level==='por terminarse'?'selected':''}>Por terminarse</option></select></div><div class="field"><label>Fecha de elaboración de la mamadera</label><input name="madeDate" type="date" value="${esc(inv.sauce?.madeDate||'')}"></div><div class="field"><label>Fecha de vencimiento de la mamadera</label><input name="expiresAt" type="date" value="${esc(inv.sauce?.expiresAt||'')}"></div>`;
    else if(p.control==='reusable')fields+=`<div class="field"><label>Estado</label><select name="qty"><option value="bien" ${inv.qty==='bien'?'selected':''}>Está bien</option><option value="cambiar" ${inv.qty==='cambiar'?'selected':''}>Cambiar</option></select></div>`;
    else if(p.control==='medallions')fields+=`<div class="field"><label>Cantidad total de medallones</label><input name="qty" type="number" min="0" step="1" value="${esc(inv.qty||0)}"></div><div class="field"><label>De ese total, congelados</label><input name="frozenQty" type="number" min="0" step="1" value="${esc(inv.frozenQty||0)}"></div><div class="field"><label>Fecha de elaboración (medallones frescos)</label><input name="madeDate" type="date" value="${esc(inv.madeDate||'')}"></div><div class="field"><label>Vencimiento (medallones frescos)</label><input name="expiresAt" type="date" value="${esc(inv.expiresAt||'')}"></div>`;
    else fields+=`<div class="field"><label>Cantidad / peso (${esc(p.unit)})</label><input name="qty" type="number" min="0" step="any" value="${esc(inv.qty||0)}"></div>`;
    if(p.expiryMode==='dateonly')fields+=`<div class="field"><label>Fecha de vencimiento</label><input name="expiresAt" type="date" value="${esc(inv.expiresAt||'')}"><span class="field-help">Verdura fresca: se registra solo el vencimiento.</span></div>`;
    if(p.expiryMode==='production'&&p.control!=='medallions'&&p.control!=='sauce')fields+=`<div class="field"><label>Fecha de elaboración / ingreso</label><input name="madeDate" type="date" value="${esc(inv.madeDate||'')}"></div><div class="field"><label>Fecha de vencimiento</label><input name="expiresAt" type="date" value="${esc(inv.expiresAt||'')}"></div>`;
    if(p.control!=='reusable')fields+=`<div class="field"><label>Estado de cierre</label><select name="status"><option value="hay" ${inv.status==='hay'?'selected':''}>Hay</option><option value="poco" ${inv.status==='poco'?'selected':''}>Hay poco</option><option value="no" ${inv.status==='no'?'selected':''}>No hay</option></select></div>`;
    openModal(`Editar · ${p.name}`,`<form id="modal-form" data-form="stock-edit" data-id="${pid}"><div class="form-grid">${fields}</div><div class="btn-row" style="margin-top:16px"><button class="btn" type="submit">Guardar cambios</button><button class="btn secondary" type="button" data-action="close-modal">Cancelar</button></div></form>`);
  }
  function renderLotsModal(pid){const p=getProduct(pid),inv=getInv(pid);if(!p)return;const lots=(inv.batches||[]).slice().sort((a,b)=>(a.status==='available'?0:1)-(b.status==='available'?0:1)||(a.expiresAt||'9999-12-31').localeCompare(b.expiresAt||'9999-12-31'));const body=`<div class="alert-box">Cada lote se registra completo. Cuando se utilice o se descarte, se descuenta entero del stock. Las fechas son independientes entre lotes.</div><form id="modal-form" data-form="add-lot" data-id="${pid}" style="margin-top:13px"><h3 class="section-heading">Agregar preparación / lote</h3><div class="form-grid"><div class="field"><label>Nombre o referencia (opcional)</label><input name="label" placeholder="Ej. Preparación del turno mañana"></div><div class="field"><label>Cantidad del lote (${esc(p.unit)})</label><input name="qty" type="number" min="0.01" step="any" required></div><div class="field"><label>Fecha de elaboración</label><input name="madeDate" type="date" value="${todayISO()}" required></div><div class="field"><label>Fecha de vencimiento</label><input name="expiresAt" type="date" required></div></div><div class="btn-row" style="margin-top:12px"><button class="btn" type="submit">Guardar lote y sumar al stock</button></div></form><div class="divider"></div><h3 class="section-heading">Lotes registrados</h3>${lots.length?lots.map(b=>`<div class="lot-card"><div class="lot-head"><div class="lot-title">${esc(b.label||'Lote')} · ${fmt(b.qty)} ${esc(p.unit)}</div>${b.status==='available'?expiryBadge(b.expiresAt):`<span class="status-badge neutral">${b.status==='used'?'Utilizado':'Descartado'}</span>`}</div><div class="lot-meta">Elaboración: ${fmtDate(b.madeDate)} · Vencimiento: ${fmtDate(b.expiresAt)}</div>${b.status==='available'?`<div class="btn-row" style="margin-top:8px">${daysUntil(b.expiresAt)>=0?`<button class="btn secondary small" data-action="finish-lot" data-id="${pid}" data-lot="${b.id}" data-kind="used">Marcar utilizado</button>`:''}<button class="btn danger-btn small" data-action="finish-lot" data-id="${pid}" data-lot="${b.id}" data-kind="discarded">Descartar lote</button></div>`:''}</div>`).join(''):'<div class="empty-state">Todavía no hay lotes registrados.</div>'}`;openModal(`Lotes · ${p.name}`,body);}
  function renderSauceModal(pid){const p=getProduct(pid),inv=getInv(pid),s=inv.sauce||{level:'llena',batches:[]};const batches=(s.batches||[]).slice().sort((a,b)=>(a.status==='available'?0:1)-(b.status==='available'?0:1)||(a.expiresAt||'9999-12-31').localeCompare(b.expiresAt||'9999-12-31'));const body=`<div class="alert-box">Cada salsa tiene su mamadera de servicio y puede tener lotes de reserva. Cada lote de reserva equivale a una mamadera llena. Al reemplazar una mamadera, se incorpora el vencimiento del lote elegido.</div><form id="modal-form" data-form="sauce-active" data-id="${pid}" style="margin-top:13px"><h3 class="section-heading">Mamadera en uso</h3><div class="form-grid"><div class="field"><label>Capacidad actual</label><select name="level"><option value="llena" ${s.level==='llena'?'selected':''}>Llena</option><option value="mitad" ${s.level==='mitad'?'selected':''}>A la mitad</option><option value="por terminarse" ${s.level==='por terminarse'?'selected':''}>Por terminarse</option></select></div><div class="field"><label>Fecha de elaboración</label><input name="madeDate" type="date" value="${esc(s.madeDate||'')}"></div><div class="field"><label>Fecha de vencimiento</label><input name="expiresAt" type="date" value="${esc(s.expiresAt||'')}"></div><div class="field"><label>Estado del cierre</label><select name="status"><option value="hay" ${inv.status==='hay'?'selected':''}>Hay</option><option value="poco" ${inv.status==='poco'?'selected':''}>Hay poco</option><option value="no" ${inv.status==='no'?'selected':''}>No hay</option></select></div></div><div class="btn-row" style="margin-top:10px"><button class="btn secondary" type="submit">Guardar mamadera</button></div></form><div class="divider"></div><form id="modal-form-reserve" data-form="sauce-reserve" data-id="${pid}"><h3 class="section-heading">Preparar lote de reserva</h3><p class="subtle">Un lote equivale a una mamadera llena y queda listo para rellenar o reemplazar la de servicio.</p><div class="form-grid"><div class="field"><label>Referencia (opcional)</label><input name="label" placeholder="Ej. Reserva turno tarde"></div><div class="field"><label>Fecha de elaboración</label><input name="madeDate" type="date" value="${todayISO()}" required></div><div class="field"><label>Fecha de vencimiento</label><input name="expiresAt" type="date" required></div></div><button class="btn" type="submit" style="margin-top:10px">Guardar lote de reserva</button></form><div class="divider"></div><h3 class="section-heading">Reservas disponibles</h3>${batches.length?batches.map(b=>`<div class="lot-card"><div class="lot-head"><div class="lot-title">${esc(b.label||'Mamadera de reserva')}</div>${b.status==='available'?expiryBadge(b.expiresAt):`<span class="status-badge neutral">${b.status==='used'?'Utilizado':'Descartado'}</span>`}</div><div class="lot-meta">Elaboración: ${fmtDate(b.madeDate)} · Vencimiento: ${fmtDate(b.expiresAt)}</div>${b.status==='available'?`<div class="btn-row" style="margin-top:8px">${daysUntil(b.expiresAt)>=0?`<button class="btn secondary small" data-action="refill-sauce" data-id="${pid}" data-lot="${b.id}">Reemplazar mamadera con este lote</button>`:''}<button class="btn danger-btn small" data-action="discard-sauce-lot" data-id="${pid}" data-lot="${b.id}">Descartar</button></div>`:''}</div>`).join(''):'<div class="empty-state">No hay mamaderas de reserva.</div>'}`;openModal(`Mamadera · ${p.name}`,body);}
  function openModal(title,body){$('#modal-root').innerHTML=`<div class="modal-backdrop" data-action="backdrop-close"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>${esc(title)}</h2><button class="modal-close" data-action="close-modal" aria-label="Cerrar">×</button></div><div class="modal-body">${body}</div></div></div>`;}
  function closeModal(){$('#modal-root').innerHTML='';}
  function finishLot(pid,lotId,kind){const p=getProduct(pid),inv=getInv(pid),lot=(inv.batches||[]).find(b=>b.id===lotId);if(!p||!lot||lot.status!=='available')return;if(kind==='used'&&daysUntil(lot.expiresAt)<0){toast('El lote ya venció: debe descartarse, no marcarse como utilizado.');return;}if(!confirm(kind==='discarded'?'¿Descartar este lote completo? Se descontará del stock.':'¿Marcar este lote como utilizado? Se descontará completo del stock.'))return;lot.status=kind;lot.closedAt=new Date().toISOString();if(typeof inv.qty==='number')inv.qty=Math.max(0,inv.qty-parseNumber(lot.qty));else if(p.control==='potatoes'){}if(kind==='discarded')addEntry({kind:'descarte',productId:pid,qty:parseNumber(lot.qty),unit:p.unit,date:todayISO(),note:'Lote descartado por vencimiento o deterioro'});saveState();renderStock();renderLotsModal(pid);toast(kind==='discarded'?'Lote descartado y descontado.':'Lote utilizado y descontado.');}
  function finishSauceLot(pid,lotId,kind){const inv=getInv(pid),lot=(inv.sauce?.batches||[]).find(b=>b.id===lotId);if(!lot||lot.status!=='available')return;if(!confirm('¿Descartar este lote de reserva?'))return;lot.status='discarded';lot.closedAt=new Date().toISOString();saveState();renderSauceModal(pid);toast('Lote de reserva descartado.');}

  function addEntry(entry){state.entries.push({id:id(),date:entry.date||todayISO(),createdAt:new Date().toISOString(),...entry});}
  function addBatchToProduct(p,inv,{label,qty,madeDate,expiresAt}){const batch={id:id(),label:label||'Lote',qty:parseNumber(qty),madeDate,expiresAt,status:'available',createdAt:new Date().toISOString()};inv.batches=inv.batches||[];inv.batches.push(batch);inv.qty=(typeof inv.qty==='number'?inv.qty:0)+batch.qty;inv.updatedAt=new Date().toISOString();return batch;}
  function stockEditSubmit(form){const pid=form.dataset.id,p=getProduct(pid),inv=getInv(pid);const beforeQty=qtyNumeric(p,inv),fd=new FormData(form);if(p.control==='potatoes')inv.qty={bags:Math.max(0,parseNumber(fd.get('bags'))),openKg:Math.max(0,parseNumber(fd.get('openKg')))};else if(p.control==='sauce'){inv.sauce.level=fd.get('level')||'llena';inv.sauce.madeDate=fd.get('madeDate')||'';inv.sauce.expiresAt=fd.get('expiresAt')||'';inv.status=fd.get('status')||'hay';}else if(p.control==='reusable')inv.qty=fd.get('qty')||'bien';else {inv.qty=Math.max(0,parseNumber(fd.get('qty')));if(p.control==='medallions'){inv.frozenQty=Math.min(inv.qty,Math.max(0,parseNumber(fd.get('frozenQty'))));inv.madeDate=fd.get('madeDate')||'';inv.expiresAt=fd.get('expiresAt')||(p.shelfLifeDays&&inv.madeDate?dateAdd(inv.madeDate,p.shelfLifeDays):'');}else if(p.expiryMode==='production'){inv.madeDate=fd.get('madeDate')||'';inv.expiresAt=fd.get('expiresAt')||(p.shelfLifeDays&&inv.madeDate?dateAdd(inv.madeDate,p.shelfLifeDays):'');}else if(p.expiryMode==='dateonly')inv.expiresAt=fd.get('expiresAt')||'';}
    if(p.control==='reusable')inv.status=inv.qty;else if(p.control!=='sauce')inv.status=fd.get('status')||inv.status||'sin-registro';const afterQty=qtyNumeric(p,inv);if((p.control!=='reusable'&&(p.control!=='potatoes'||p.bagWeightKg>0))&&Number.isFinite(beforeQty)&&Number.isFinite(afterQty)&&Math.abs(afterQty-beforeQty)>0.0001)addEntry({kind:afterQty>beforeQty?'ajuste-in':'ajuste-out',productId:pid,qty:Math.abs(afterQty-beforeQty),unit:p.control==='potatoes'?'kg':p.unit,date:todayISO(),note:'Ajuste manual de Stock actual'});inv.updatedAt=new Date().toISOString();saveState();closeModal();renderStock();toast('Stock actualizado.');}
  function addLotSubmit(form){const pid=form.dataset.id,p=getProduct(pid),inv=getInv(pid),fd=new FormData(form);const q=parseNumber(fd.get('qty')),made=fd.get('madeDate'),exp=fd.get('expiresAt');if(!q||!made||!exp){toast('Completá cantidad y las dos fechas.');return;}if(exp<made){toast('El vencimiento no puede ser anterior a la elaboración.');return;}addBatchToProduct(p,inv,{label:fd.get('label'),qty:q,madeDate:made,expiresAt:exp});addEntry({kind:'elaboracion',productId:pid,qty:q,unit:p.unit,date:todayISO(),note:`Lote elaborado el ${fmtDate(made)}; agregado desde Stock actual`});saveState();closeModal();renderStock();toast('Lote agregado y stock actualizado.');}
  function sauceActiveSubmit(form){const pid=form.dataset.id,p=getProduct(pid),inv=getInv(pid),fd=new FormData(form),made=fd.get('madeDate')||'',exp=fd.get('expiresAt')||'',before=qtyNumeric(p,inv);if(made&&exp&&exp<made){toast('El vencimiento no puede ser anterior a la elaboración.');return;}inv.sauce.level=fd.get('level')||'llena';inv.sauce.madeDate=made;inv.sauce.expiresAt=exp;inv.status=fd.get('status')||'hay';const after=qtyNumeric(p,inv);if(Math.abs(after-before)>0.0001)addEntry({kind:after>before?'ajuste-in':'ajuste-out',productId:pid,qty:Math.abs(after-before),unit:'equiv. mamadera',date:todayISO(),note:'Ajuste manual de cantidad en mamadera'});saveState();closeModal();renderStock();toast('Mamadera actualizada.');}
  function sauceReserveSubmit(form){const pid=form.dataset.id,inv=getInv(pid),fd=new FormData(form);const made=fd.get('madeDate'),exp=fd.get('expiresAt');if(!made||!exp||exp<made){toast('Revisá las fechas del lote.');return;}inv.sauce.batches=inv.sauce.batches||[];inv.sauce.batches.push({id:id(),label:fd.get('label')||'Mamadera de reserva',madeDate:made,expiresAt:exp,status:'available',createdAt:new Date().toISOString()});addEntry({kind:'reserva-salsa',productId:pid,qty:1,unit:'mamadera',date:todayISO(),note:`Mamadera de reserva elaborada el ${fmtDate(made)}`});saveState();renderSauceModal(pid);toast('Lote de reserva registrado.');}
  function refillSauce(pid,lotId){const p=getProduct(pid),inv=getInv(pid),lot=(inv.sauce?.batches||[]).find(b=>b.id===lotId);if(!p||!lot||lot.status!=='available')return;if(daysUntil(lot.expiresAt)<0){toast('La reserva ya venció: debe descartarse.');return;}if(!confirm(`¿Reemplazar la mamadera de ${p.name} por esta reserva? La mamadera actual quedará fuera de servicio.`))return;const remaining=qtyNumeric(p,inv);if(remaining>0)addEntry({kind:'descarte',productId:pid,qty:remaining,unit:'equiv. mamadera',date:todayISO(),note:'Contenido restante de mamadera reemplazada'});lot.status='used';lot.closedAt=new Date().toISOString();inv.sauce.level='llena';inv.sauce.madeDate=lot.madeDate;inv.sauce.expiresAt=lot.expiresAt;inv.status='hay';addEntry({kind:'trans-in',productId:pid,qty:1,unit:'mamadera',date:todayISO(),note:'Mamadera de reserva puesta en servicio'});saveState();renderSauceModal(pid);toast('Mamadera reemplazada con el lote elegido.');}
  function incomeFields(type){const pOptions=activeProducts().filter(p=>!['reusable','sauce'].includes(p.control)&&p.track!=='lots').map(p=>`<option value="${p.id}">${esc(p.name)}${p.control==='potatoes'?' (bolsas cerradas)':` (${esc(p.unit)})`}</option>`).join('');const transformOptions=activeProducts().filter(p=>!['reusable','sauce','potatoes'].includes(p.control)&&p.track!=='lots').map(p=>`<option value="${p.id}">${esc(p.name)} (${esc(p.unit)})</option>`).join('');if(type==='transformacion')return `<div class="form-grid"><div class="field"><label>Producto de origen</label><select name="sourceProductId" required>${transformOptions}</select></div><div class="field"><label>Cantidad utilizada</label><input name="sourceQty" type="number" min="0.01" step="any" required></div><div class="field"><label>Producto resultante</label><select name="productId" required>${transformOptions}</select></div><div class="field"><label>Cantidad elaborada</label><input name="qty" type="number" min="0.01" step="any" required></div><div class="field"><label>Fecha de la transformación</label><input name="date" type="date" value="${todayISO()}" required></div><div class="field"><label>Si el resultado son medallones</label><select name="medallionState"><option value="frescos">Frescos</option><option value="congelados">Congelados</option></select></div><div class="field"><label>Observación</label><input name="note" placeholder="Ej. Carne molida convertida en medallones"></div></div><p class="field-help">Las fechas de elaboración y vencimiento se cargan después, exclusivamente desde Stock actual.</p>`;
    return `<div class="form-grid"><div class="field"><label>Producto</label><select name="productId" required>${pOptions}</select></div><div class="field"><label>Cantidad ingresada</label><input name="qty" type="number" min="0.01" step="any" required></div><div class="field"><label>Fecha del movimiento</label><input name="date" type="date" value="${todayISO()}" required></div><div class="field"><label>Si el producto son medallones</label><select name="medallionState"><option value="frescos">Frescos</option><option value="congelados">Congelados</option></select></div><div class="field"><label>Observación</label><input name="note" placeholder="Proveedor, tanda, detalle…"></div></div><p class="field-help">Las fechas se registran únicamente en Stock actual. Preparaciones con lotes y salsas se ingresan desde sus fichas de Stock actual. Para papas, ingresá bolsas cerradas; los kilos de la bolsa abierta se ajustan en Stock actual.</p>`;
  }
  function renderIngresos(){const type=$('#income-type')?.value||'compra';let html=pageHead('Ingresos','Registrá compras, elaboraciones y transformaciones internas. Las fechas se cargan exclusivamente desde Stock actual.',`<button class="btn secondary" data-go="stock">Ver stock actual</button>`);
    html+=`<section class="panel"><h2 class="panel-title">Registrar movimiento</h2><div class="field" style="max-width:380px;margin-bottom:13px"><label>Tipo de movimiento</label><select id="income-type"><option value="compra">Compra de mercadería</option><option value="elaboracion">Elaboración propia</option><option value="transformacion">Transformación interna</option></select></div><form id="income-form" data-form="income"><div id="income-fields">${incomeFields('compra')}</div><div class="btn-row" style="margin-top:14px"><button class="btn" type="submit">Guardar ingreso</button></div></form></section>`;
    const entries=state.entries.slice().sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt)).slice(0,30);
    html+=`<section class="panel"><h2 class="panel-title">Movimientos recientes</h2>${entries.length?`<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Tipo</th><th>Producto</th><th>Cantidad</th><th>Detalle</th></tr></thead><tbody>${entries.map(e=>{const p=getProduct(e.productId);const source=getProduct(e.sourceProductId);let label=e.kind==='compra'?'Compra':e.kind==='elaboracion'?'Elaboración':e.kind==='trans-in'?'Transformación recibida':e.kind==='trans-out'?'Transformación utilizada':e.kind==='descarte'?'Descarte':e.kind==='reserva-salsa'?'Reserva de salsa':e.kind==='ajuste-in'?'Ajuste positivo':e.kind==='ajuste-out'?'Ajuste negativo':e.kind;return `<tr><td>${fmtDate(e.date)}</td><td>${esc(label)}</td><td>${esc(p?.name||'Producto eliminado')}${source?`<div class="row-note">Origen: ${esc(source.name)}</div>`:''}</td><td>${fmt(e.qty)} ${esc(e.unit||p?.unit||'')}</td><td>${esc(e.note||'—')}</td></tr>`;}).join('')}</tbody></table></div>`:'<div class="empty-state">Todavía no hay compras ni elaboraciones registradas.</div>'}</section>`;
    $('#main').innerHTML=html;
  }
  function incomeSubmit(form){const fd=new FormData(form),type=$('#income-type')?.value||'compra',date=fd.get('date')||todayISO();if(type==='transformacion'){const sourceId=fd.get('sourceProductId'),destId=fd.get('productId'),sourceQty=parseNumber(fd.get('sourceQty')),qty=parseNumber(fd.get('qty')),source=getProduct(sourceId),dest=getProduct(destId);if(!source||!dest||sourceId===destId||sourceQty<=0||qty<=0){toast('Completá los productos y cantidades de la transformación.');return;}const srcInv=getInv(sourceId),destInv=getInv(destId);if(qtyNumeric(source,srcInv)<sourceQty){toast('El stock de origen no alcanza para esa transformación.');return;}if(dest.track==='lots'||dest.control==='sauce'||dest.control==='potatoes'){toast('Este producto se ingresa desde Stock actual para registrar su lote y vencimiento.');return;}if(typeof srcInv.qty!=='number'){toast('Este tipo de producto no admite transformación automática.');return;}if(dest.control==='medallions'){destInv.qty=parseNumber(destInv.qty)+qty;if(fd.get('medallionState')==='congelados'){destInv.frozenQty=parseNumber(destInv.frozenQty)+qty;}else{destInv.madeDate='';destInv.expiresAt='';}}else if(typeof destInv.qty==='number')destInv.qty+=qty;else{toast('El producto resultante no admite esta transformación.');return;}srcInv.qty=Math.max(0,srcInv.qty-sourceQty);addEntry({kind:'trans-out',productId:sourceId,qty:sourceQty,unit:source.unit,date,note:fd.get('note')||`Transformado en ${dest.name}`});addEntry({kind:'trans-in',productId:destId,qty,unit:dest.unit,date,note:fd.get('note')||`Elaborado desde ${source.name}`});saveState();renderIngresos();toast(dest.control==='medallions'&&fd.get('medallionState')==='frescos'?'Transformación registrada. Cargá la elaboración y el vencimiento desde Stock actual.':'Transformación registrada.');return;}
    const pid=fd.get('productId'),p=getProduct(pid),inv=getInv(pid),qty=parseNumber(fd.get('qty'));if(!p||qty<=0){toast('Ingresá una cantidad válida.');return;}if(p.track==='lots'||p.control==='sauce'){toast('Este producto se ingresa desde Stock actual para registrar su cantidad y sus datos especiales.');return;}if(p.control==='potatoes'){inv.qty=inv.qty||{bags:0,openKg:0};inv.qty.bags=parseNumber(inv.qty.bags)+qty;}else if(p.control==='medallions'){inv.qty=parseNumber(inv.qty)+qty;if(fd.get('medallionState')==='congelados')inv.frozenQty=parseNumber(inv.frozenQty)+qty;else{inv.madeDate='';inv.expiresAt='';}}else if(typeof inv.qty==='number')inv.qty+=qty;else{toast('No se puede sumar una cantidad a este tipo de producto desde Ingresos.');return;}
    if(p.expiryMode==='production'&&p.control!=='medallions'){inv.madeDate='';inv.expiresAt='';}if(p.expiryMode==='dateonly')inv.expiresAt='';inv.updatedAt=new Date().toISOString();addEntry({kind:type,productId:pid,qty,unit:p.control==='potatoes'?'bolsas':p.unit,date,note:fd.get('note')||''});saveState();renderIngresos();toast(type==='compra'?'Compra registrada. Cargá las fechas desde Stock actual si corresponde.':'Elaboración registrada. Cargá las fechas desde Stock actual si corresponde.');}

  function itemQtyForStats(p,item){if(!item)return 0;if(p.control==='reusable')return null;if(p.control==='potatoes')return p.bagWeightKg>0?(parseNumber(item.qty?.bags)*Number(p.bagWeightKg)+parseNumber(item.qty?.openKg)):null;if(p.control==='sauce')return item.qty==='llena'?1:(item.qty==='mitad'?0.5:(item.qty==='por terminarse'?0.2:0));return parseNumber(item.qty);}
  function computeUsage(){const out={};const closures=state.closures.slice().sort((a,b)=>a.date.localeCompare(b.date)||a.createdAt.localeCompare(b.createdAt));if(closures.length<2)return out;
    activeProducts().forEach(p=>{if(p.control==='reusable')return;out[p.id]={total:0,ordinary:0,peak:0,ordinaryDays:0,peakDays:0,intervals:0,incomplete:false};});
    for(let i=1;i<closures.length;i++){const prev=closures[i-1],curr=closures[i];const d0=new Date(`${prev.date}T12:00:00`),d1=new Date(`${curr.date}T12:00:00`);const diff=Math.round((d1-d0)/86400000);if(diff<=0)continue;const start=dateAdd(prev.date,1),prevStamp=Date.parse(prev.createdAt||`${prev.date}T00:00:00`),currStamp=Date.parse(curr.createdAt||`${curr.date}T23:59:59`);const entries=state.entries.filter(e=>{const stamp=Date.parse(e.createdAt||`${e.date}T12:00:00`);return stamp>prevStamp&&stamp<=currStamp;});const sums={};entries.forEach(e=>{if(!sums[e.productId])sums[e.productId]={in:0,transOut:0,discard:0,adjustOut:0};const s=sums[e.productId],ep=getProduct(e.productId),movementQty=ep?.control==='potatoes'&&e.unit==='bolsas'&&ep.bagWeightKg>0?parseNumber(e.qty)*Number(ep.bagWeightKg):parseNumber(e.qty);if(['compra','elaboracion','trans-in','ajuste-in'].includes(e.kind))s.in+=movementQty;if(e.kind==='trans-out')s.transOut+=movementQty;if(e.kind==='descarte')s.discard+=movementQty;if(e.kind==='ajuste-out')s.adjustOut=(s.adjustOut||0)+movementQty;});
      for(const p of activeProducts()){const s=out[p.id];if(!s)continue;const before=itemQtyForStats(p,prev.items.find(x=>x.productId===p.id));const after=itemQtyForStats(p,curr.items.find(x=>x.productId===p.id));if(before===null||after===null)continue;const mov=sums[p.id]||{in:0,transOut:0,discard:0,adjustOut:0};const used=before+mov.in-after-mov.transOut-mov.discard-(mov.adjustOut||0);if(used<0){s.incomplete=true;continue;}s.total+=used;s.intervals++;
        const each=used/diff;for(let k=0;k<diff;k++){const day=new Date(`${dateAdd(start,k)}T12:00:00`).getDay();if(day===5||day===6){s.peak+=each;s.peakDays++;}else{s.ordinary+=each;s.ordinaryDays++;}}
      }
    }
    Object.values(out).forEach(s=>{s.avgOrdinary=s.ordinaryDays?s.ordinary/s.ordinaryDays:0;s.avgPeak=s.peakDays?s.peak/s.peakDays:0;s.avgDay=(s.ordinary+s.peak)/(s.ordinaryDays+s.peakDays||1);s.weekly=s.avgOrdinary*Number(state.settings.ordinaryDays||5)+s.avgPeak*Number(state.settings.peakDays||2);});return out;
  }
  function planningQty(p,inv){if(p.control==='sauce')return qtyNumeric(p,inv)+(inv.sauce?.batches||[]).filter(b=>b.status==='available').length;return qtyNumeric(p,inv);}
  function computePlanningUsage(){const automatic=computeUsage(),manual=state.settings.manualUsage||{},out={};activeProducts().forEach(p=>{if(p.control==='reusable')return;const a=automatic[p.id],m=manual[p.id]||{},hasManual=Number(m.ordinary||0)>0||Number(m.peak||0)>0,hasAuto=!!(a&&a.intervals>0);if(!hasManual&&!hasAuto)return;const source=hasAuto?'automática':'manual';const ordinary=hasAuto?a.avgOrdinary:Number(m.ordinary||0),peak=hasAuto?a.avgPeak:Number(m.peak||0),ordinaryDays=Number(state.settings.ordinaryDays||5),peakDays=Number(state.settings.peakDays||2),weekly=ordinary*ordinaryDays+peak*peakDays;out[p.id]={...(a||{}),avgOrdinary:ordinary,avgPeak:peak,avgDay:(ordinary*ordinaryDays+peak*peakDays)/(ordinaryDays+peakDays||1),weekly,total:(a?.total||0),intervals:a?.intervals||0,source,manualOrdinary:Number(m.ordinary||0),manualPeak:Number(m.peak||0),autoOrdinary:a?.avgOrdinary||0,autoPeak:a?.avgPeak||0,incomplete:a?.incomplete||false};});return out;}
  function manualUsagePanel(){const groups={};activeProducts().filter(p=>p.control!=='reusable').forEach(p=>(groups[p.category]??=[]).push(p));let html='<div class="manual-usage-wrap"><p class="subtle">Cargá cuánto se utiliza habitualmente por día. Para viernes y sábado podés indicar otro promedio. Estos valores sirven como referencia inicial; cuando existan cierres comparables, la estadística automática pasará a ser la referencia principal y podrás seguir viendo lo que cargaste manualmente.</p>';for(const [cat,products] of Object.entries(groups)){html+=`<details class="manual-category"><summary>${esc(cat)} <span>${products.length} productos</span></summary><div class="table-wrap"><table><thead><tr><th>Producto</th><th>Uso habitual / día</th><th>Vie. y sáb. / día</th></tr></thead><tbody>`;for(const p of products){const m=state.settings.manualUsage?.[p.id]||{},unit=p.control==='potatoes'?'kg':p.control==='sauce'?'mamaderas':p.unit;html+=`<tr><td><strong>${esc(p.name)}</strong><div class="row-note">${esc(unit)}${p.control==='potatoes'?' (equivalente en kg)':''}</div></td><td><input class="manual-usage-input" type="number" min="0" step="0.1" data-manual-product="${esc(p.id)}" data-manual-kind="ordinary" value="${m.ordinary??''}" placeholder="0"></td><td><input class="manual-usage-input" type="number" min="0" step="0.1" data-manual-product="${esc(p.id)}" data-manual-kind="peak" value="${m.peak??''}" placeholder="0"></td></tr>`;}html+='</tbody></table></div></details>';}return html+'</div><div class="btn-row" style="margin-top:12px"><button class="btn" data-action="save-manual-usage">Guardar estadísticas manuales</button></div>'; }
  function estimatedShelfLife(p){if(p.shelfLifeDays)return Number(p.shelfLifeDays);if(p.track==='lots'){const durations=(getInv(p.id).batches||[]).filter(b=>b.madeDate&&b.expiresAt).map(b=>Math.max(1,daysBetween(b.madeDate,b.expiresAt)));if(durations.length)return durations.reduce((a,b)=>a+b,0)/durations.length;}return null;}
  function daysBetween(a,b){return Math.max(0,Math.round((new Date(`${b}T12:00:00`)-new Date(`${a}T12:00:00`))/86400000));}
  function buildRecommendations(){const rec=[],stats=computePlanningUsage(),exp=getAllExpirations();exp.filter(x=>daysUntil(x.expiresAt)<=1).forEach(x=>rec.push({title:`Priorizar ${x.product.name}`,text:`${x.label}: ${daysUntil(x.expiresAt)<0?'ya venció':'vence '+(daysUntil(x.expiresAt)===0?'hoy':'mañana')}. Revisar y priorizar o descartar según corresponda.`,tag:'Vencimiento'}));
    const meat=getProduct('carne-molida'),patties=getProduct('medallones');if(meat&&patties&&stats['medallones']?.avgDay>0){const ms=stats['medallones'],expected=ms.avgDay*3,pattyInv=getInv(patties.id),pattyStock=qtyNumeric(patties,pattyInv),frozen=parseNumber(pattyInv.frozenQty),fresh=Math.max(0,pattyStock-frozen),meatKg=qtyNumeric(meat,getInv(meat.id)),kg=Math.max(0,(expected-pattyStock)*.1-meatKg);rec.push({title:'Planificar carne fresca para 3 días',text:`Demanda estimada: ${fmt(expected,0)} medallones. Disponibles: ${fmt(fresh,0)} frescos y ${fmt(frozen,0)} congelados. Compra orientativa de carne molida: ${fmt(kg)} kg, descontando la carne y los medallones ya disponibles.`,tag:'Próximos 3 días'});const meatExpiry=getInv(meat.id).expiresAt,meatDays=daysUntil(meatExpiry);if(meatExpiry&&meatDays>=0&&meatDays<=1&&meatKg>0)rec.push({title:'Revisar excedente de carne molida',text:`Hay ${fmt(meatKg)} kg y vence ${meatDays===0?'hoy':'mañana'}. Priorizá su uso fresco; si no se va a utilizar a tiempo, evaluá transformarla en medallones y congelarlos antes de su vencimiento, según el procedimiento de la cocina.`,tag:'Rotación urgente'});}
    Object.entries(stats).forEach(([pid,s])=>{const p=getProduct(pid);if(!p||s.weekly<=0)return;const inv=getInv(pid),current=planningQty(p,inv),shelf=estimatedShelfLife(p);if(current>0&&s.avgDay>0){const coverage=current/s.avgDay;if(coverage>7)rec.push({title:`Revisar rotación: ${p.name}`,text:`El stock actual cubre aproximadamente ${fmt(coverage,1)} días al ritmo registrado. Evaluar reducir la próxima compra o elaboración.`,tag:'Baja rotación'});if(['poco','no'].includes(inv.status)){const horizon=shelf?Math.min(7,Math.max(1,shelf)):7;const need=Math.max(0,s.avgDay*horizon-current);if(need>0)rec.push({title:`Reposición sugerida: ${p.name}`,text:`Para cubrir ${horizon} días al consumo estimado, faltarían ${fmt(need)} ${p.control==='potatoes'?'kg':p.unit}.`,tag:'Reposición'});}}});return rec.slice(0,30);}
  function renderRotation(){const stats=computePlanningUsage(),data=Object.entries(stats).map(([pid,s])=>({p:getProduct(pid),s})).filter(x=>x.p&&x.s.weekly>0).sort((a,b)=>b.s.weekly-a.s.weekly);const expiries=getAllExpirations(),soon=expiries.filter(x=>daysUntil(x.expiresAt)<=1);const slow=data.filter(({p,s})=>s.avgDay>0&&planningQty(p,getInv(p.id))/s.avgDay>7).sort((a,b)=>(planningQty(b.p,getInv(b.p.id))/b.s.avgDay)-(planningQty(a.p,getInv(a.p.id))/a.s.avgDay));
    let html=pageHead('Rotación y planificación','Compará cierres, identificá productos de poca salida y planificá compras y elaboraciones según consumo y vencimientos.',`<button class="btn secondary" data-go="ingresos">Registrar ingreso</button>`);
    html+=`<div class="grid grid-4"><div class="card stat-card"><div class="stat-label">Cierres guardados</div><div class="stat-value">${state.closures.length}</div><div class="stat-foot">Se necesitan al menos dos para comparar</div></div><div class="card stat-card"><div class="stat-label">Productos con uso estimado</div><div class="stat-value">${data.length}</div><div class="stat-foot">Con datos comparables</div></div><div class="card stat-card"><div class="stat-label">Vence hoy o mañana</div><div class="stat-value">${soon.length}</div><div class="stat-foot">Lotes y productos con fecha</div></div><div class="card stat-card"><div class="stat-label">Cobertura alta</div><div class="stat-value">${slow.length}</div><div class="stat-foot">Más de 7 días al ritmo registrado</div></div></div>`;
    if(state.closures.length<2)html+=`<div class="alert-box" style="margin-top:14px">Todavía no hay suficientes cierres para una estadística automática. Podés cargar una estimación manual por producto y la aplicación la usará como referencia inicial. Registrá también compras, elaboraciones y transformaciones para mejorar los cálculos automáticos.</div>`;
    html+=panel('Estadística manual de uso',manualUsagePanel(),'Ingresá el uso promedio por día para cada producto y preparación. Se guarda por separado de los datos automáticos.');
    html+=`<div class="grid grid-2" style="margin-top:15px">${panel('Promedio por día de actividad',`<div class="kpi"><span>Habitual: Lun–Jue y dom.</span><span>Pico: viernes y sábado</span></div><p class="subtle">La estimación distribuye el consumo entre las fechas comprendidas entre dos cierres.</p><div class="field"><label>Días habituales por semana</label><input id="ordinary-days" type="number" min="0" max="7" step="1" value="${state.settings.ordinaryDays}"></div><div class="field" style="margin-top:8px"><label>Viernes y sábados</label><input id="peak-days" type="number" min="0" max="7" step="1" value="${state.settings.peakDays}"></div><button class="btn secondary small" data-action="save-plan-days" style="margin-top:9px">Guardar días de planificación</button>`,`La cantidad semanal se calcula con estos días y los promedios observados.`)}${panel('Prioridades de vencimiento',soon.length?soon.map(x=>`<div class="list-row"><div class="row-main"><div class="row-title">${esc(x.product.name)} · ${esc(x.label)}</div><div class="row-note">Vence: ${fmtDate(x.expiresAt)}</div></div>${expiryBadge(x.expiresAt)}</div>`).join(''):'<div class="empty-state">No hay lotes con vencimiento hoy o mañana.</div>')}</div>`;
    html+=panel('Consumo y elaboración estimada',data.length?`<div class="table-wrap"><table><thead><tr><th>Producto</th><th>Manual habitual</th><th>Auto. habitual</th><th>Manual vie/sáb</th><th>Auto. vie/sáb</th><th>Proyección semanal</th><th>Referencia usada</th><th>Stock actual</th><th>Cobertura</th></tr></thead><tbody>${data.map(({p,s})=>{const current=planningQty(p,getInv(p.id)),coverage=s.avgDay>0?current/s.avgDay:null,statUnit=p.control==='potatoes'?'kg':p.unit;const stockLabel=p.control==='sauce'?`${qtyDisplay(p,getInv(p.id))} + ${(getInv(p.id).sauce?.batches||[]).filter(b=>b.status==='available').length} reservas`:p.control==='potatoes'?qtyDisplay(p,getInv(p.id)):fmt(current);return `<tr><td><strong>${esc(p.name)}</strong>${s.incomplete?'<div class="row-note">Hay un intervalo con movimientos incompletos</div>':''}</td><td>${fmt(s.manualOrdinary)} ${esc(statUnit)}</td><td>${fmt(s.autoOrdinary)} ${esc(statUnit)}</td><td>${fmt(s.manualPeak)} ${esc(statUnit)}</td><td>${fmt(s.autoPeak)} ${esc(statUnit)}</td><td><strong>${fmt(s.weekly)} ${esc(statUnit)}</strong></td><td><span class="tag">${s.source==='automática'?'Automática':'Manual'}</span></td><td>${stockLabel} ${p.control==='sauce'||p.control==='potatoes'?'':' '+esc(p.unit)}</td><td>${coverage===null?'—':fmt(coverage,1)+' días'}</td></tr>`;}).join('')}</tbody></table></div>`:'<div class="empty-state">Todavía no hay datos suficientes para comparar productos.<strong>Guardá dos cierres y registrá los ingresos entre ellos.</strong></div>','La proyección semanal separa días habituales de viernes y sábado. Es una estimación, no una orden de producción.');
    const rec=buildRecommendations();html+=panel('Recomendaciones de compra y rotación',rec.length?rec.map(r=>`<div class="list-row"><div class="row-main"><div class="row-title">${esc(r.title)}</div><div class="row-note">${esc(r.text)}</div></div><span class="tag">${esc(r.tag)}</span></div>`).join(''):'<div class="empty-state">Las recomendaciones aparecerán a medida que registres cierres, ingresos y vencimientos.</div>','La aplicación prioriza vencimientos reales y cobertura calculada según el uso observado.');
    html+=`<div class="alert-box">Para incluir papas en la estadística de uso, configurá primero el peso real de una bolsa cerrada en Configuración. La app no supone un peso de bolsa.
<br>Importante: el consumo se estima como stock anterior + ingresos − stock final, descontando transformaciones y descartes registrados. Si se omite una compra, elaboración o descarte, la estadística puede distorsionarse. Las recomendaciones de compra no reemplazan el control sanitario ni las indicaciones de conservación del proveedor.</div>`;
    $('#main').innerHTML=html;
  }

  function renderOrders(){const candidates=activeProducts().filter(p=>p.control==='reusable'?getInv(p.id).qty==='cambiar':['poco','no'].includes(getInv(p.id).status));const orders=state.orders||[];const merged=candidates.map(p=>orders.find(o=>o.productId===p.id)||{id:p.id,productId:p.id,name:p.name,qty:qtyDisplay(p,getInv(p.id)),status:getInv(p.id).status,bought:false,manual:false});const manual=orders.filter(o=>o.manual);const list=[...merged,...manual];
    const rows=list.length?list.map(o=>{const p=getProduct(o.productId);return `<div class="list-row"><label style="display:flex;gap:9px;align-items:center;flex:1"><input type="checkbox" data-action="toggle-order" data-id="${esc(o.id)}" ${o.bought?'checked':''}><span class="row-main"><span class="row-title">${esc(o.name||p?.name||'Producto')}</span><span class="row-note">${esc(o.qty|| (p?qtyDisplay(p,getInv(p.id)):'Agregar cantidad'))} · ${o.manual?'Agregado manualmente':(p?.control==='reusable'?'Cambiar':statusText(o.status||'poco'))}</span></span></label><button class="btn ghost small" data-action="remove-order" data-id="${esc(o.id)}">Quitar</button></div>`;}).join(''):'<div class="empty-state">No hay productos pendientes.<strong>Los productos Hay poco o No hay aparecerán automáticamente.</strong></div>';
    $('#main').innerHTML=pageHead('Pedidos','Lista automática de productos que necesitan reposición, más artículos que quieras agregar manualmente.',`<button class="btn secondary" data-action="share-orders">Compartir lista</button>`)+`<section class="panel"><div class="panel-title">Lista de compras <span class="tag">${list.filter(o=>!o.bought).length} pendientes</span></div>${rows}<div class="divider"></div><form id="manual-order-form" class="form-grid"><div class="field"><label>Agregar producto</label><input name="name" placeholder="Ej. Film adherente" required></div><div class="field"><label>Cantidad (opcional)</label><input name="qty" placeholder="Ej. 2 rollos"></div><div class="btn-row" style="grid-column:1/-1"><button class="btn" type="submit">＋ Agregar a pedidos</button></div></form></section><div class="alert-box">Al marcar un artículo como comprado, se elimina de pendientes pero no cambia el inventario. Para actualizar cantidades, registrá la compra en Ingresos.</div>`;
  }
  function toggleOrder(oid,checked){let o=(state.orders||[]).find(x=>x.id===oid);if(!o){const p=getProduct(oid);if(!p)return;o={id:oid,productId:oid,name:p.name,qty:qtyDisplay(p,getInv(p.id)),status:getInv(p.id).status,bought:false,manual:false};state.orders.push(o);}o.bought=checked;saveState();renderOrders();}
  function shareOrders(){const candidates=activeProducts().filter(p=>p.control==='reusable'?getInv(p.id).qty==='cambiar':['poco','no'].includes(getInv(p.id).status));const items=[...candidates.map(p=>({name:p.name,qty:qtyDisplay(p,getInv(p.id)),bought:(state.orders||[]).find(o=>o.productId===p.id)?.bought||false})),...(state.orders||[]).filter(o=>o.manual).map(o=>({name:o.name,qty:o.qty,bought:o.bought}))].filter(o=>!o.bought);const text='LISTA DE PEDIDOS\n'+(items.length?items.map(o=>`• ${o.name}${o.qty?` — ${o.qty}`:''}`).join('\n'):'Sin productos pendientes.');if(navigator.share)navigator.share({text}).catch(()=>{});else navigator.clipboard?.writeText(text).then(()=>toast('Lista copiada.')).catch(()=>toast(text));}
  function renderHistory(){const closes=state.closures.slice().sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt));let html=pageHead('Historial','Consultá los cierres guardados. Podés corregir la fecha o eliminar un cierre individual.');html+=`<section class="panel"><h2 class="panel-title">Cierres registrados <span class="tag">${closes.length}</span></h2>${closes.length?`<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Productos</th><th>Registrado</th><th>Acciones</th></tr></thead><tbody>${closes.map(c=>`<tr><td><strong>${fmtDate(c.date)}</strong></td><td>${c.items.length}</td><td>${new Date(c.createdAt).toLocaleString('es-AR')}</td><td><div class="btn-row"><button class="btn secondary small" data-action="view-close" data-id="${c.id}">Ver</button><button class="btn ghost small" data-action="edit-close-date" data-id="${c.id}">Fecha</button><button class="btn danger-btn small" data-action="delete-close" data-id="${c.id}">Eliminar</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">Todavía no hay cierres guardados.</div>'}</section>`;$('#main').innerHTML=html;}
  function viewClose(cid){const c=state.closures.find(x=>x.id===cid);if(!c)return;const rows=c.items.map(i=>{const p=getProduct(i.productId);return `<div class="list-row"><div class="row-main"><div class="row-title">${esc(p?.name||'Producto')}</div><div class="row-note">${p?formatItemQty(p,i,getInv(p.id)):'—'}</div></div><span class="status-badge ${statusClass(i.status)}">${statusText(i.status)}</span></div>`;}).join('');openModal(`Cierre · ${fmtDate(c.date)}`,`${rows}<div class="btn-row" style="margin-top:14px"><button class="btn" data-action="copy-close-by-id" data-id="${cid}">Copiar mensaje de este cierre</button></div>`);}
  function editCloseDate(cid){const c=state.closures.find(x=>x.id===cid);if(!c)return;openModal('Editar fecha del cierre',`<form id="modal-form" data-form="edit-close-date" data-id="${cid}"><div class="field"><label>Nueva fecha</label><input name="date" type="date" value="${c.date}" required></div><div class="alert-box" style="margin-top:10px">Solo cambia la fecha histórica. No modifica cantidades, lotes ni vencimientos del inventario.</div><div class="btn-row" style="margin-top:14px"><button class="btn" type="submit">Guardar fecha</button><button class="btn secondary" type="button" data-action="close-modal">Cancelar</button></div></form>`);}
  function renderWork(){const all=state.shifts.slice().sort((a,b)=>b.date.localeCompare(a.date));const active=all.filter(s=>!s.archived);const now=new Date(),month=now.toISOString().slice(0,7);const day=new Date();const monday=new Date(day);monday.setDate(day.getDate()-((day.getDay()+6)%7));const mondayISO=new Date(monday.getTime()-monday.getTimezoneOffset()*60000).toISOString().slice(0,10);const week=all.filter(s=>s.date>=mondayISO&&s.date<=todayISO());const monthShifts=all.filter(s=>s.date.startsWith(month));const sum=list=>list.reduce((a,s)=>a+parseNumber(s.finalAmount),0);const hours=list=>list.reduce((a,s)=>a+parseNumber(s.hours),0);
    $('#main').innerHTML=pageHead('Mi trabajo','Registrá jornadas, calculá automáticamente el pago y corregí el importe cuando sea necesario.')+`<div class="grid grid-3"><div class="card stat-card"><div class="stat-label">Ganancias esta semana</div><div class="stat-value">$ ${fmt(sum(week))}</div><div class="stat-foot">${fmt(hours(week))} horas registradas</div></div><div class="card stat-card"><div class="stat-label">Ganancias este mes</div><div class="stat-value">$ ${fmt(sum(monthShifts))}</div><div class="stat-foot">${fmt(hours(monthShifts))} horas registradas</div></div><div class="card stat-card"><div class="stat-label">Tarifa por hora</div><div class="stat-value">$ ${fmt(state.settings.hourlyRate)}</div><div class="stat-foot">Podés modificarla en cada jornada</div></div></div><section class="panel" style="margin-top:15px"><h2 class="panel-title">Registrar jornada</h2><form id="shift-form" data-form="shift"><div class="form-grid"><div class="field"><label>Fecha</label><input type="date" name="date" value="${todayISO()}" required></div><div class="field"><label>Valor por hora ($)</label><input type="number" name="rate" id="shift-rate" min="0" step="any" value="${state.settings.hourlyRate||''}" required></div><div class="field"><label>Hora de entrada</label><input type="time" name="start" id="shift-start" required></div><div class="field"><label>Hora de salida</label><input type="time" name="end" id="shift-end" required></div><div class="field"><label>Horas trabajadas (automático)</label><input name="hours" id="shift-hours" readonly placeholder="Se calcula con los horarios"></div><div class="field"><label>Pago calculado (editable)</label><input name="finalAmount" id="shift-amount" type="number" min="0" step="any" required placeholder="Se calcula automáticamente"></div></div><div class="field" style="margin-top:10px"><label>Observaciones (opcional)</label><input name="note" placeholder="Turno extra, feriado…"></div><div class="btn-row" style="margin-top:14px"><button class="btn" type="submit">Guardar jornada</button></div></form><p class="field-help">El importe final queda guardado en la jornada. Cambiar la tarifa más adelante no modifica jornadas anteriores.</p></section><section class="panel"><div class="panel-title">Jornadas registradas <span class="tag">${all.length}</span></div>${all.length?all.map(s=>`<div class="shift-card"><div class="shift-top"><div><div class="row-title">${fmtDate(s.date)} ${s.archived?'<span class="tag">Archivada</span>':''}</div><div class="row-note">${s.start} a ${s.end} · ${fmt(s.hours)} horas · $ ${fmt(s.finalAmount)}</div>${s.note?`<div class="row-note">${esc(s.note)}</div>`:''}</div><div class="btn-row"><button class="btn ghost small" data-action="archive-shift" data-id="${s.id}">${s.archived?'Desarchivar':'Archivar'}</button><button class="btn danger-btn small" data-action="delete-shift" data-id="${s.id}">Eliminar</button></div></div></div>`).join(''):'<div class="empty-state">Todavía no registraste jornadas.</div>'}</section>`;
  }
  function calcShiftHours(start,end){if(!start||!end)return 0;let [sh,sm]=start.split(':').map(Number),[eh,em]=end.split(':').map(Number);let mins=eh*60+em-(sh*60+sm);if(mins<0)mins+=1440;return Math.round(mins/60*100)/100;}
  function updateShiftPreview(){const f=$('#shift-form');if(!f)return;const fd=new FormData(f),h=calcShiftHours(fd.get('start'),fd.get('end')),rate=parseNumber(fd.get('rate'));$('#shift-hours').value=h?fmt(h,2):'';const amount=$('#shift-amount');if(amount&&!amount.dataset.manual)amount.value=h?String(Math.round(h*rate*100)/100):'';}

  function productSettingsModal(pid){const p=pid?getProduct(pid):null;const val=(key,fallback='')=>p?.[key]??fallback;const body=`<form id="modal-form" data-form="product-settings" data-id="${pid||''}"><div class="form-grid"><div class="field"><label>Nombre del producto</label><input name="name" value="${esc(val('name'))}" required></div><div class="field"><label>Categoría</label><select name="category">${state.categories.map(c=>`<option ${val('category')===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>Unidad de medida</label><input name="unit" value="${esc(val('unit','unidades'))}" placeholder="kg, unidades, porciones…" required></div><div class="field"><label>Tipo de contabilización</label><select name="control"><option value="number" ${val('control','number')==='number'?'selected':''}>Cantidad o peso</option><option value="medallions" ${val('control')==='medallions'?'selected':''}>Medallones (total + congelados)</option><option value="potatoes" ${val('control')==='potatoes'?'selected':''}>Papas (bolsas + kg abierto)</option><option value="sauce" ${val('control')==='sauce'?'selected':''}>Mamadera de salsa</option><option value="reusable" ${val('control')==='reusable'?'selected':''}>Está bien / Cambiar</option></select></div><div class="field"><label>Control de vencimiento</label><select name="expiryMode"><option value="none" ${val('expiryMode','none')==='none'?'selected':''}>No requiere vencimiento</option><option value="dateonly" ${val('expiryMode')==='dateonly'?'selected':''}>Solo fecha de vencimiento</option><option value="production" ${val('expiryMode')==='production'?'selected':''}>Elaboración e ingreso + vencimiento</option><option value="lots" ${val('expiryMode')==='lots'?'selected':''}>Por lotes de preparación</option><option value="sauce" ${val('expiryMode')==='sauce'?'selected':''}>Mamadera y lotes de reserva</option></select></div><div class="field"><label>Tipo de lotes</label><select name="track"><option value="none" ${val('track','none')==='none'?'selected':''}>Sin lotes</option><option value="lots" ${val('track')==='lots'?'selected':''}>Lotes completos</option><option value="sauce" ${val('track')==='sauce'?'selected':''}>Mamadera + reservas</option></select></div><div class="field"><label>Duración de referencia (días, opcional)</label><input name="shelfLifeDays" type="number" min="1" step="1" value="${esc(val('shelfLifeDays',''))}" placeholder="Se puede aprender de los lotes"></div><div class="field"><label>Peso de bolsa cerrada (kg, solo papas)</label><input name="bagWeightKg" type="number" min="0.1" step="0.1" value="${esc(val('bagWeightKg',''))}" placeholder="No se supone un peso"></div><div class="field"><label>Incluir en mensaje de WhatsApp</label><select name="wa"><option value="true" ${val('wa',true)?'selected':''}>Sí</option><option value="false" ${val('wa',true)===false?'selected':''}>No</option></select></div></div><div class="btn-row" style="margin-top:15px"><button class="btn" type="submit">${p?'Guardar producto':'Crear producto'}</button><button class="btn secondary" type="button" data-action="close-modal">Cancelar</button></div></form>`;openModal(p?'Editar producto':'Agregar producto',body);}
  function productSettingsSubmit(form){const fd=new FormData(form),pid=form.dataset.id;let p=pid?getProduct(pid):null;const rawShelf=fd.get('shelfLifeDays');const data={name:String(fd.get('name')).trim(),category:fd.get('category'),unit:String(fd.get('unit')).trim(),control:fd.get('control'),expiryMode:fd.get('expiryMode'),track:fd.get('track'),shelfLifeDays:rawShelf?parseNumber(rawShelf):null,bagWeightKg:fd.get('bagWeightKg')?parseNumber(fd.get('bagWeightKg')):null,wa:fd.get('wa')==='true',active:true};if(!data.name||!data.category||!data.unit){toast('Completá nombre, categoría y unidad.');return;}if(p){Object.assign(p,data);if(!state.inventory[p.id])state.inventory[p.id]=freshInventory(p);}else{p={id:'custom-'+id(),...data};state.products.push(p);state.inventory[p.id]=freshInventory(p);}saveState();closeModal();renderSettings();toast('Producto guardado.');}
  function renderSettings(){const groups=productGroups();let html=pageHead('Configuración','Administrá categorías, productos, unidades y reglas de contabilización.',`<button class="btn" data-action="add-product">＋ Agregar producto</button>`);
    html+=`<div class="grid grid-2"><section class="panel"><h2 class="panel-title">Categorías</h2><form id="category-form" class="form-grid"><div class="field"><label>Nueva categoría</label><input name="name" placeholder="Nombre de categoría" required></div><div class="field" style="align-self:end"><button class="btn" type="submit">Agregar categoría</button></div></form><div class="divider"></div>${state.categories.map(c=>`<div class="list-row"><div class="row-title">${esc(c)}</div><div class="btn-row"><span class="tag">${(groups[c]||[]).length} productos</span><button class="btn ghost small" data-action="delete-category" data-id="${esc(c)}">Eliminar</button></div></div>`).join('')}</section><section class="panel"><h2 class="panel-title">Datos y respaldo</h2><p class="subtle">Los datos quedan guardados en este navegador. Exportá una copia de seguridad cada tanto, especialmente antes de cambiar de teléfono.</p><div class="btn-row"><button class="btn secondary" data-action="export-data">Exportar copia JSON</button><label class="btn ghost" for="import-file">Importar copia</label><input type="file" id="import-file" accept="application/json,.json" class="hidden"></div><div class="divider"></div><div class="field"><label>Tarifa por hora predeterminada ($)</label><input id="default-rate" type="number" min="0" step="any" value="${state.settings.hourlyRate||0}"></div><button class="btn secondary small" data-action="save-rate" style="margin-top:9px">Guardar tarifa</button><div class="alert-box" style="margin-top:14px">La aplicación funciona sin una cuenta y guarda la información localmente. Si borrás los datos del navegador o desinstalás la app, podrías perderlos. Usá Exportar copia JSON para resguardarlos.</div></section></div>`;
    html+=`<section class="panel"><div class="panel-title">Productos <span class="tag">${activeProducts().length}</span></div><div class="filter-bar"><input id="settings-search" type="search" placeholder="Buscar producto…"></div><div class="table-wrap"><table><thead><tr><th>Producto</th><th>Categoría</th><th>Unidad</th><th>Vencimiento</th><th>WhatsApp</th><th>Acciones</th></tr></thead><tbody>${activeProducts().map(p=>`<tr data-setting-product="${p.id}"><td><strong>${esc(p.name)}</strong></td><td>${esc(p.category)}</td><td>${esc(p.unit)}</td><td>${esc(p.expiryMode)}</td><td>${p.wa?'Sí':'No'}</td><td><div class="btn-row"><button class="btn secondary small" data-action="edit-product" data-id="${p.id}">Editar</button><button class="btn danger-btn small" data-action="delete-product" data-id="${p.id}">Eliminar</button></div></td></tr>`).join('')}</tbody></table></div></section>`;
    $('#main').innerHTML=html;
  }
  function deleteProduct(pid){const p=getProduct(pid);if(!p||!confirm(`¿Eliminar ${p.name} de la lista activa? Los registros históricos se conservarán.`))return;p.active=false;saveState();renderSettings();toast('Producto retirado del inventario activo.');}
  function deleteCategory(cat){if(activeProducts().some(p=>p.category===cat)){toast('Primero mové o eliminá los productos de esta categoría.');return;}if(!confirm(`¿Eliminar la categoría ${cat}?`))return;state.categories=state.categories.filter(c=>c!==cat);saveState();renderSettings();}
  function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`STOCK-copia-${todayISO()}.json`;a.click();URL.revokeObjectURL(url);toast('Copia de seguridad descargada.');}
  function importData(file){const reader=new FileReader();reader.onload=()=>{try{const incoming=JSON.parse(reader.result);if(!incoming||!Array.isArray(incoming.products)||!Array.isArray(incoming.closures))throw new Error('Formato no válido');if(!confirm('Importar reemplazará los datos guardados en esta app. ¿Continuar?'))return;state={...createInitialState(),...incoming};saveState();go('inicio');toast('Copia importada.');}catch(e){toast('No se pudo importar: archivo inválido.');}};reader.readAsText(file);}
  function moreMenu(){openModal('Más secciones',`<div class="grid grid-2">${navItems.slice(4).map(([key,icon,label])=>`<button class="nav-btn" style="background:#f4e7d1;border:1px solid #e0c8a5" data-go="${key}"><span class="nav-icon">${icon}</span>${label}</button>`).join('')}</div>`);}

  function renderPage(){switch(currentPage){case 'inicio':dashboard();break;case 'cierre':renderClosure();break;case 'stock':renderStock();break;case 'rotacion':renderRotation();break;case 'ingresos':renderIngresos();break;case 'pedidos':renderOrders();break;case 'trabajo':renderWork();break;case 'historial':renderHistory();break;case 'configuracion':renderSettings();break;default:currentPage='inicio';dashboard();}}

  document.addEventListener('click',e=>{
    const goBtn=e.target.closest('[data-go]');if(goBtn){const page=goBtn.dataset.go;closeModal();go(page);return;}
    const btn=e.target.closest('[data-action]');if(!btn)return;const action=btn.dataset.action,idv=btn.dataset.id;
    switch(action){
      case 'close-modal':closeModal();break;
      case 'backdrop-close':if(e.target.classList.contains('modal-backdrop'))closeModal();break;
      case 'more-menu':moreMenu();break;
      case 'save-close':saveClose();break;
      case 'preview-message':previewMessage();break;
      case 'copy-message':copyMessage();break;
      case 'copy-last-message':{const c=state.closures.slice().sort((a,b)=>a.date.localeCompare(b.date)).at(-1);if(!c){toast('Todavía no hay cierres.');break;}openModal('Mensaje del último cierre',`<textarea id="wa-message" class="control" rows="16">${esc(buildWhatsAppMessage(c))}</textarea><button class="btn" data-action="copy-message" style="margin-top:10px">Copiar mensaje</button>`);break;}
      case 'share-message':shareMessage();break;
      case 'edit-stock':renderStockEditModal(idv);break;
      case 'manage-lots':renderLotsModal(idv);break;
      case 'manage-sauce':renderSauceModal(idv);break;
      case 'finish-lot':finishLot(idv,btn.dataset.lot,btn.dataset.kind);break;
      case 'discard-sauce-lot':finishSauceLot(idv,btn.dataset.lot,'discarded');break;
      case 'refill-sauce':refillSauce(idv,btn.dataset.lot);break;
      case 'refresh-stock':renderStock();break;
      case 'share-orders':shareOrders();break;
      case 'remove-order':if(confirm('¿Quitar este artículo de la lista?')){state.orders=state.orders.filter(o=>o.id!==idv);saveState();renderOrders();}break;
      case 'view-close':viewClose(idv);break;
      case 'edit-close-date':editCloseDate(idv);break;
      case 'delete-close':if(confirm('¿Eliminar este cierre del historial? No se revertirá el stock actual.')){state.closures=state.closures.filter(c=>c.id!==idv);saveState();renderHistory();toast('Cierre eliminado del historial.');}break;
      case 'copy-close-by-id':{const c=state.closures.find(x=>x.id===idv);if(!c)break;const text=buildWhatsAppMessage(c);navigator.clipboard?.writeText(text).then(()=>toast('Mensaje copiado.')).catch(()=>openModal('Mensaje del cierre',`<textarea class="control" rows="16">${esc(text)}</textarea>`));break;}
      case 'archive-shift':{const s=state.shifts.find(x=>x.id===idv);if(s){s.archived=!s.archived;saveState();renderWork();toast(s.archived?'Jornada archivada.':'Jornada desarchivada.');}break;}
      case 'delete-shift':if(confirm('¿Eliminar esta jornada?')){state.shifts=state.shifts.filter(s=>s.id!==idv);saveState();renderWork();}break;
      case 'add-product':productSettingsModal(null);break;
      case 'edit-product':productSettingsModal(idv);break;
      case 'delete-product':deleteProduct(idv);break;
      case 'delete-category':deleteCategory(idv);break;
      case 'export-data':exportData();break;
      case 'save-rate':state.settings.hourlyRate=Math.max(0,parseNumber($('#default-rate')?.value));saveState();toast('Tarifa predeterminada guardada.');break;
      case 'save-plan-days':state.settings.ordinaryDays=Math.max(0,Math.min(7,parseNumber($('#ordinary-days')?.value)));state.settings.peakDays=Math.max(0,Math.min(7,parseNumber($('#peak-days')?.value)));saveState();renderRotation();toast('Días de planificación guardados.');break;
      case 'save-manual-usage':{state.settings.manualUsage=state.settings.manualUsage||{};$$('[data-manual-product]').forEach(input=>{const pid=input.dataset.manualProduct,kind=input.dataset.manualKind;state.settings.manualUsage[pid]=state.settings.manualUsage[pid]||{ordinary:0,peak:0};state.settings.manualUsage[pid][kind]=Math.max(0,parseNumber(input.value));});saveState();renderRotation();toast('Estadísticas manuales guardadas.');break;}
    }
  });

  document.addEventListener('change',e=>{
    if(e.target.id==='stock-category'){selectedCategory=e.target.value;renderStock();}
    if(e.target.id==='stock-search'){stockQuery=e.target.value;renderStock();}
    if(e.target.id==='income-type'){const el=$('#income-fields');if(el)el.innerHTML=incomeFields(e.target.value);}
    if(e.target.id==='import-file'&&e.target.files?.[0])importData(e.target.files[0]);
    if(e.target.matches('[data-action="toggle-order"]'))toggleOrder(e.target.dataset.id,e.target.checked);
  });
  document.addEventListener('input',e=>{
    if(e.target.id==='shift-rate'||e.target.id==='shift-start'||e.target.id==='shift-end'){const amount=$('#shift-amount');if(amount)amount.dataset.manual='';updateShiftPreview();}
    if(e.target.id==='shift-amount')e.target.dataset.manual='1';
    if(e.target.id==='settings-search'){const q=e.target.value.toLowerCase();$$('[data-setting-product]').forEach(row=>row.classList.toggle('hidden',!row.textContent.toLowerCase().includes(q)));}
  });
  document.addEventListener('submit',e=>{
    const form=e.target;if(!form.matches('form'))return;const kind=form.dataset.form;
    if(kind||['income-form','manual-order-form','category-form','shift-form'].includes(form.id))e.preventDefault();
    if(kind==='stock-edit')stockEditSubmit(form);
    else if(kind==='add-lot')addLotSubmit(form);
    else if(kind==='sauce-active')sauceActiveSubmit(form);
    else if(kind==='sauce-reserve')sauceReserveSubmit(form);
    else if(kind==='product-settings')productSettingsSubmit(form);
    else if(kind==='edit-close-date'){const c=state.closures.find(x=>x.id===form.dataset.id);const fd=new FormData(form);if(c&&fd.get('date')){c.date=fd.get('date');saveState();closeModal();renderHistory();toast('Fecha del cierre actualizada.');}}
    else if(kind==='income')incomeSubmit(form);
    else if(form.id==='manual-order-form'){const fd=new FormData(form),name=String(fd.get('name')||'').trim();if(!name)return;state.orders.push({id:id(),productId:null,name,qty:String(fd.get('qty')||''),status:'poco',bought:false,manual:true});saveState();renderOrders();toast('Producto agregado a pedidos.');}
    else if(form.id==='category-form'){const fd=new FormData(form),name=String(fd.get('name')||'').trim();if(name&&!state.categories.includes(name)){state.categories.push(name);saveState();renderSettings();toast('Categoría agregada.');}}
    else if(kind==='shift'){const fd=new FormData(form),hours=calcShiftHours(fd.get('start'),fd.get('end'));if(!hours){toast('Revisá el horario de entrada y salida.');return;}const rate=parseNumber(fd.get('rate')),amount=parseNumber(fd.get('finalAmount'));state.shifts.push({id:id(),date:fd.get('date')||todayISO(),start:fd.get('start'),end:fd.get('end'),hours,rate,calculatedAmount:hours*rate,finalAmount:amount,note:fd.get('note')||'',archived:false,createdAt:new Date().toISOString()});state.settings.hourlyRate=rate;saveState();renderWork();toast('Jornada guardada.');}
  });

  // La PWA se instala y actualiza sin depender de servicios externos.
  if('serviceWorker' in navigator && location.protocol.startsWith('http')) navigator.serviceWorker.register('./sw.js').then(()=>{const s=$('#connection-status');if(s)s.innerHTML='<i></i> App lista';}).catch(()=>{});
  window.addEventListener('online',()=>{const s=$('#connection-status');if(s)s.innerHTML='<i></i> En línea';});
  window.addEventListener('offline',()=>{const s=$('#connection-status');if(s)s.innerHTML='<i></i> Sin conexión';});
  drawNavigation();renderPage();saveState();
})();
